const items = $input.all();
const out = [];

function safeString(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(safeString).join(', ');
  if (typeof value === 'object') {
    if (value.value !== undefined) return safeString(value.value);
    if (value.text !== undefined) return safeString(value.text);
    if (value.email && value.name) return `${value.name} <${value.email}>`;
    if (value.email) return String(value.email);
    if (value.address) return String(value.address);
    try { return JSON.stringify(value); } catch {}
  }
  return String(value);
}

function getHeader(headers, name) {
  if (!Array.isArray(headers)) return '';
  const h = headers.find(x => x && String(x.name || '').toLowerCase() === name.toLowerCase());
  return h ? safeString(h.value) : '';
}

function decodeB64Url(data) {
  if (!data) return '';
  try {
    return Buffer.from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function collectParts(part, acc) {
  if (!part || typeof part !== 'object') return;
  const mime = String(part.mimeType || '').toLowerCase();
  const data = part.body?.data ? decodeB64Url(part.body.data) : '';
  if (data && mime === 'text/plain') acc.plain.push(data);
  if (data && mime === 'text/html') acc.html.push(data);
  if (part.filename) acc.attachments.push({
    filename: String(part.filename),
    mimeType: String(part.mimeType || ''),
    attachmentId: part.body?.attachmentId || null
  });
  for (const child of (part.parts || [])) collectParts(child, acc);
}

function htmlToText(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractJsonLd(html) {
  const found = [];
  const re = /<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = re.exec(String(html || ''))) !== null && found.length < 10) {
    const raw = m[1].trim();
    if (!raw) continue;
    try { found.push(JSON.parse(raw)); }
    catch { found.push({ raw: raw.slice(0, 12000) }); }
  }
  return found;
}

for (const item of items) {
  const email = item.json || {};
  const payload = email.payload || {};
  const payloadHeaders = payload.headers || [];
  const directHeaders = email.headers || {};

  const from = safeString(email.from || directHeaders.from || directHeaders.From || getHeader(payloadHeaders, 'from'));
  const to = safeString(email.to || directHeaders.to || directHeaders.To || getHeader(payloadHeaders, 'to'));
  const cc = safeString(email.cc || directHeaders.cc || directHeaders.Cc || getHeader(payloadHeaders, 'cc'));
  const subject = safeString(email.subject || directHeaders.subject || directHeaders.Subject || getHeader(payloadHeaders, 'subject'));
  const date = safeString(email.date || email.internalDate || directHeaders.date || directHeaders.Date || getHeader(payloadHeaders, 'date'));
  const replyTo = safeString(email.replyTo || getHeader(payloadHeaders, 'reply-to'));

  let senderEmail = from;
  let senderName = '';
  const angle = from.match(/^(?:"?([^"<]*)"?\s*)?<([^>]+)>$/);
  if (angle) {
    senderName = String(angle[1] || '').trim();
    senderEmail = String(angle[2] || '').trim();
  } else if (from.includes('@')) {
    const m = from.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    if (m) senderEmail = m[0];
    senderName = from.replace(senderEmail, '').replace(/[<>"]/g, '').trim();
  }
  const senderDomain = senderEmail.includes('@') ? senderEmail.split('@').pop().toLowerCase() : '';

  const parts = { plain: [], html: [], attachments: [] };
  collectParts(payload, parts);

  let rawHtml = safeString(email.textHtml || email.html || parts.html.join('\n'));
  let bodyText = safeString(email.textPlain || email.text || parts.plain.join('\n'));
  if (!bodyText && rawHtml) bodyText = htmlToText(rawHtml);
  if (!bodyText) bodyText = safeString(email.snippet);

  bodyText = String(bodyText || '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  // Keep much more context than the original template's 3000-char cut.
  // We still cap runaway newsletters so the local model isn't fed megabytes.
  const bodyForAI = bodyText.slice(0, 16000);
  const bodyWasTruncated = bodyText.length > bodyForAI.length;
  const jsonLd = extractJsonLd(rawHtml);

  const attachmentList = [
    ...parts.attachments,
    ...(Array.isArray(email.attachments) ? email.attachments.map(a => ({
      filename: String(a.filename || ''),
      mimeType: String(a.mimeType || a.mime_type || ''),
      attachmentId: a.attachmentId || a.attachment_id || null
    })) : [])
  ];

  out.push({
    json: {
      gmailId: String(email.id || email.messageId || email.message_id || ''),
      threadId: String(email.threadId || email.thread_id || ''),
      labelIds: email.labelIds || email.labels || [],
      from,
      senderName,
      senderEmail,
      senderDomain,
      to,
      cc,
      replyTo: replyTo || senderEmail,
      subject,
      date,
      bodyText: bodyForAI,
      bodyPreview: bodyForAI.slice(0, 500),
      bodyWasTruncated,
      originalBodyLength: bodyText.length,
      jsonLd,
      hasAttachments: attachmentList.length > 0,
      attachments: attachmentList.slice(0, 20),
      isReply: /^re:/i.test(subject),
      isForward: /^(fwd|fw):/i.test(subject),
      processedAt: new Date().toISOString()
    }
  });
}

return out;

const e = $json;
let body = String(e.bodyText || '');
if (Array.isArray(e.jsonLd) && e.jsonLd.length) {
  body += '\n\n[EMAIL_STRUCTURED_JSON_LD]\n' + JSON.stringify(e.jsonLd).slice(0, 16000);
}

return [{
  json: {
    request_id: `gmail-${e.gmailId || Date.now()}`,
    email: {
      from: e.from || e.senderEmail || '',
      subject: e.subject || '',
      body,
      received_at: e.date || null
    },
    candidates: [],
    source_context: {
      source: 'gmail-trigger',
      gmail_id: e.gmailId || '',
      thread_id: e.threadId || '',
      sender_domain: e.senderDomain || '',
      has_attachments: !!e.hasAttachments,
      body_was_truncated: !!e.bodyWasTruncated,
      original_body_length: Number(e.originalBodyLength || 0),
      identity_lookup_status: 'NOT_CONNECTED_SAFE_REVIEW'
    }
  }
}];

// SAFETY PLACEHOLDER.
// Until BuyFlow Identity Graph / Supabase candidate lookup is connected,
// lifecycle emails receive candidates=[] so Agent+Critic must REVIEW instead
// of guessing a purchase. ORDER_CREATED may still become CREATE_PURCHASE.
return $input.all().map(item => ({
  json: {
    ...item.json,
    candidates: [],
    source_context: {
      ...(item.json.source_context || {}),
      identity_lookup_status: 'NOT_CONNECTED_SAFE_REVIEW'
    }
  }
}));

const req = $('🧾 Build BuyFlow Request').item.json;
const result = $json;

return [{
  json: {
    shadow_only: true,
    gmail_id: req.source_context?.gmail_id || null,
    thread_id: req.source_context?.thread_id || null,
    sender_domain: req.source_context?.sender_domain || null,
    identity_lookup_status: req.source_context?.identity_lookup_status || 'UNKNOWN',
    write_performed: false,
    buyflow_result: result,
    audited_at: new Date().toISOString()
  }
}];
